class AuditStore:
    """Append-only in-memory store for migrated audit events."""

    __slots__ = ("__events",)

    def __init__(self) -> None:
        self.__events: tuple[dict, ...] = ()

    def append(self, event: dict) -> None:
        self.__events += (event.copy(),)

    def events(self) -> list[dict]:
        return [event.copy() for event in self.__events]

    def __len__(self) -> int:
        return len(self.__events)


def migrate_event(row: dict) -> dict:
    timestamp = row["EVT_TS"]
    return {
        "evt_id": int(row["EVT_ID"]),
        "ts": (
            f"{timestamp[0:4]}-{timestamp[4:6]}-{timestamp[6:8]}"
            f"T{timestamp[8:10]}:{timestamp[10:12]}:{timestamp[12:14]}"
        ),
        "code": row["EVT_CD"],
        "user_id": row["USR_ID"],
        "entity": row["ENT_NAME"],
        "entity_id": row["ENT_ID"],
        "old_val": row["OLD_VAL"],
        "new_val": row["NEW_VAL"],
    }


def migrate(
    rows: list[dict],
    store: AuditStore | None = None,
) -> AuditStore:
    target = AuditStore() if store is None else store
    existing_ids = {
        event["evt_id"]
        for event in target.events()
        if "evt_id" in event
    }

    for row in sorted(rows, key=lambda item: int(item["EVT_ID"])):
        evt_id = int(row["EVT_ID"])
        if evt_id in existing_ids:
            continue
        target.append(migrate_event(row))
        existing_ids.add(evt_id)

    return target
